const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret) throw new Error('Missing LENDLOOP_WEBHOOK_SECRET in n8n environment');

const item = $input.first();
const sigHeader = item.json.headers?.['x-lendloop-signature'] || '';
const rawBody = JSON.stringify(item.json.body);

const parts = Object.fromEntries(sigHeader.split(',').map(p => p.trim().split('=')));
const ts = Number(parts.t);
const v1 = parts.v1 || '';
const now = Math.floor(Date.now() / 1000);

if (!Number.isFinite(ts) || Math.abs(now - ts) > 300) {
  throw new Error('Rejected webhook: Invalid or expired timestamp');
}

const expected = crypto.createHmac('sha256', secret).update(`${ts}.${rawBody}`, 'utf8').digest('hex');
const a = Buffer.from(v1, 'hex');
const b = Buffer.from(expected, 'hex');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Rejected webhook: HMAC signature verification failed');
}

// Data minimization: pass only required notification fields downstream
const bObj = item.json.body;
return [{
  json: {
    eventId: bObj.eventId,
    eventType: bObj.eventType,
    requestId: bObj.requestId,
    toolName: bObj.toolName,
    recipientEmail: bObj.recipientEmail,
    recipientRole: bObj.recipientRole,
    startDate: bObj.startDate,
    endDate: bObj.endDate
  }
}];

const crypto = require('crypto');
const item = $input.first().json;
const message = `[LendLoop Notification] To ${item.recipientEmail} (${item.recipientRole}): ${item.eventType} for "${item.toolName}" (${item.startDate} to ${item.endDate})`;
console.log(message);

const callbackPayload = JSON.stringify({
  idempotencyKey: item.eventId,
  requestId: item.requestId,
  workflowType: 'request_notification',
  summary: `Notification sent: ${item.eventType} (${new Date().toISOString().slice(0, 10)})`,
  status: 'delivered'
});
const ts = Math.floor(Date.now() / 1000);
const mac = crypto.createHmac('sha256', $env.LENDLOOP_WEBHOOK_SECRET).update(`${ts}.${callbackPayload}`, 'utf8').digest('hex');

return [{
  json: {
    callbackPayload,
    signatureHeader: `t=${ts},v1=${mac}`
  }
}];
